import { BrowserRouter, Routes, Route, Navigate } from 'react-router-dom';
import Sidebar from './components/Sidebar';
import Topbar from './components/Topbar';
import Analytics from './pages/Analytics';
import Chat from './pages/Chat';
import Upload from './pages/Upload';
import Settings from './pages/Settings';
import Login from './pages/Login';
import { useState } from 'react';

const API = 'http://localhost:8000';

export default function App() {
  const [loggedIn, setLoggedIn] = useState(true);

  if (!loggedIn) return <Login onLogin={() => setLoggedIn(true)} />;

  return (
    <BrowserRouter>
      <div style={{ display: 'flex', height: '100vh', overflow: 'hidden', position: 'relative', zIndex: 1 }}>
        <Sidebar />
        <div style={{ flex: 1, display: 'flex', flexDirection: 'column', overflow: 'hidden' }}>
          <Topbar API={API} onLogout={() => setLoggedIn(false)} />
          <div style={{ flex: 1, overflowY: 'auto', padding: '20px 24px' }}>
            <Routes>
              <Route path="/" element={<Navigate to="/analytics" />} />
              <Route path="/analytics" element={<Analytics API={API} />} />
              <Route path="/chat" element={<Chat API={API} />} />
              <Route path="/upload" element={<Upload API={API} />} />
              <Route path="/settings" element={<Settings API={API} />} />
            </Routes>
          </div>
        </div>
      </div>
    </BrowserRouter>
  );
}
